import { describe, expect, it } from 'vitest';
import { DurationError, parseDuration, scheduleJob } from './schedule.js';

describe('scheduleJob', () => {
  it('keeps the job name', () => {
    expect(scheduleJob({ name: 'sync', every: '1s' }).name).toBe('sync');
  });

